Hub.ApplyPotatoOptimizer = function(self, enabled)
	local lighting = self.Services.Lighting;
	if not self.State.PotatoBackup then
		self.State.PotatoBackup = {};
	end
	if enabled then
		if not self.State.PotatoLightingBackup then
			self.State.PotatoLightingBackup = {[LUAOBFUSACTOR_DECRYPT_STR_0("\32\75\64\241\121\80\52\79\78\247\119\75\20", "\60\103\39\47\147\24")]=lighting.GlobalShadows,FogEnd=lighting.FogEnd,Brightness=lighting.Brightness};
		end
		pcall(function()
			lighting.GlobalShadows = false;
			lighting.FogEnd = 8999999488;
			lighting.Brightness = 2;
		end);
		for _, obj in ipairs(self.Services.Workspace:GetDescendants()) do
			self:OptimizeInstance(obj);
		end
		if not self.State.OptimizerConn then
			self.State.OptimizerConn = self.Services.Workspace.DescendantAdded:Connect(function(obj)
				if self.Config.Toggles.PotatoOptimizer then
					self:OptimizeInstance(obj);
				end
			end);
		end
	else
		if self.State.PotatoLightingBackup then
			pcall(function()
				lighting.GlobalShadows = self.State.PotatoLightingBackup.GlobalShadows;
				lighting.FogEnd = self.State.PotatoLightingBackup.FogEnd;
				lighting.Brightness = self.State.PotatoLightingBackup.Brightness;
			end);
			self.State.PotatoLightingBackup = nil;
		else
			pcall(function()
				lighting.GlobalShadows = self.Config.Toggles.WorldShadows;
				lighting.FogEnd = (self.Config.Toggles.NoFog and 8999999488) or 500;
			end);
		end
		if self.State.OptimizerConn then
			self.State.OptimizerConn:Disconnect();
			self.State.OptimizerConn = nil;
		end
		for obj, data in pairs(self.State.PotatoBackup) do
			if (obj and obj.Parent) then
				pcall(function()
					if (data.Type == "BasePart") then
						obj.Material = data.Material;
						obj.CastShadow = data.CastShadow;
						obj.Reflectance = data.Reflectance;
						if (data.TextureID and obj:IsA("MeshPart")) then
							obj.TextureID = data.TextureID;
						end
					elseif (data.Type == LUAOBFUSACTOR_DECRYPT_STR_0("\200\15\244\129\218", "\46\140\106\151\224\182\147")) then
						obj.Transparency = data.Transparency;
					elseif (data.Type == LUAOBFUSACTOR_DECRYPT_STR_0("\216\61\120\65\226\44\113\111\238\62\117", "\34\139\77\29")) then
						obj.TextureId = data.TextureId;
					elseif (data.Type == "Toggleable") then
						obj.Enabled = data.Enabled;
					end
				end);
			end
		end
		table.clear(self.State.PotatoBackup);
	end
end;
Hub.OptimizeInstance = function(self, obj)
	pcall(function()
		if not self.State.PotatoBackup then
			self.State.PotatoBackup = {};
		end
		if obj:IsA("BasePart") then
			local isPlayerChar = obj.Parent and obj.Parent:FindFirstChildOfClass("Humanoid");
			if not isPlayerChar then
				if not self.State.PotatoBackup[obj] then
					self.State.PotatoBackup[obj] = {Type="BasePart",Material=obj.Material,CastShadow=obj.CastShadow,Reflectance=obj.Reflectance,TextureID=((obj:IsA("MeshPart") and obj.TextureID) or nil)};
				end
				obj.Material = Enum.Material.SmoothPlastic;
				obj.CastShadow = false;
				obj.Reflectance = 0;
				if obj:IsA("MeshPart") then
					local nm = obj.Name:lower();
					local pnm = (obj.Parent and obj.Parent.Name:lower()) or "";
					if (nm:find(LUAOBFUSACTOR_DECRYPT_STR_0("\179\255\20\90", "\73\208\144\125\52")) or pnm:find("coin")) then
						obj.TextureID = "";
					end
				end
			end
		elseif obj:IsA("SpecialMesh") then
			local pnm = (obj.Parent and obj.Parent.Name:lower()) or "";
			local ppnm = (obj.Parent and obj.Parent.Parent and obj.Parent.Parent.Name:lower()) or "";
			if (pnm:find("coin") or ppnm:find("coin")) then
				if not self.State.PotatoBackup[obj] then
					self.State.PotatoBackup[obj] = {[LUAOBFUSACTOR_DECRYPT_STR_0("\30\245\154\206", "\171\74\140\234\171\167\112\51")]="SpecialMesh",[LUAOBFUSACTOR_DECRYPT_STR_0("\27\11\84\75\228\191\42\39\72", "\205\79\110\44\63\145")]=obj.TextureId};
				end
				obj.TextureId = "";
			end
		elseif (obj:IsA("Decal") or obj:IsA("Texture")) then
			if not self.State.PotatoBackup[obj] then
				self.State.PotatoBackup[obj] = {[LUAOBFUSACTOR_DECRYPT_STR_0("\147\70\47\205", "\124\199\63\95\168\212\107\196")]="Decal",Transparency=obj.Transparency};
			end
			obj.Transparency = 1;
		elseif (obj:IsA("ParticleEmitter") or obj:IsA("Smoke") or obj:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\32\161\65\63", "\147\102\200\51\90\196\151\233")) or obj:IsA("Sparkles") or obj:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\23\249\232\197\170", "\91\91\144\143\173\222\128"))) then
			if not self.State.PotatoBackup[obj] then
				self.State.PotatoBackup[obj] = {Type="Toggleable",Enabled=obj.Enabled};
			end
			obj.Enabled = false;
		end
	end);
end;
Hub.SetFarmNoClip = function(self, on)
	local lp = self.Services.Players.LocalPlayer;
	local char = lp and lp.Character;
	local hum = char and char:FindFirstChildOfClass("Humanoid");
	if on then
		if not char then
			return;
		end
		if hum then
			pcall(function()
				hum.PlatformStand = true;
			end);
		end
		for _, p in ipairs(char:GetDescendants()) do
			if (p:IsA("BasePart") and p.CanCollide) then
				if (self.AutoFarm.NoClipCache[p] == nil) then
					self.AutoFarm.NoClipCache[p] = p.CanCollide;
				end
				p.CanCollide = false;
			end
		end
	else
		if hum then
			hum.PlatformStand = false;
			hum.Sit = false;
			hum:SetStateEnabled(Enum.HumanoidStateType.Running, true);
			hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true);
			hum:ChangeState(Enum.HumanoidStateType.GettingUp);
			task.defer(function()
				if (hum and not self.AutoFarm.IsActive) then
					hum:ChangeState(Enum.HumanoidStateType.Running);
				end
			end);
		end
		if not self.Config.Toggles.NoClip then
			for p, v in pairs(self.AutoFarm.NoClipCache or {}) do
				if (p and p.Parent) then
					pcall(function()
						p.CanCollide = v;
					end);
				end
			end
			if char then
				for _, p in ipairs(char:GetDescendants()) do
					if p:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\1\161\95\84\155\79\49\180", "\46\67\192\44\49\203")) then
						if (p.Name == "HumanoidRootPart") then
							p.CanCollide = false;
						elseif ((p.Name == "Head") or p.Name:find(LUAOBFUSACTOR_DECRYPT_STR_0("\48\217\60\177\43", "\101\100\182\78\194\68\196")) or p.Name:find("Leg") or p.Name:find(LUAOBFUSACTOR_DECRYPT_STR_0("\105\90\61", "\181\40\40\80\149\237\43\24"))) then
							p.CanCollide = true;
						end
					end
				end
			end
		end
		self.AutoFarm.NoClipCache = {};
	end
end;
Hub.ReturnToSurface = function(self)
	local lp = self.Services.Players.LocalPlayer;
	local char = lp and lp.Character;
	local root = char and self:GetRoot(char);
	local hum = char and char:FindFirstChildOfClass("Humanoid");
	if not root then
		return;
	end
	local upParams = RaycastParams.new();
	upParams.FilterType = Enum.RaycastFilterType.Exclude;
	upParams.IgnoreWater = true;
	upParams.FilterDescendantsInstances = {char};
	local res = self.Services.Workspace:Raycast(root.Position, Vector3.new(0, 400, 0), upParams);
	local y = (res and (res.Position.Y + 4)) or (self.AutoFarm.DownRefY and (self.AutoFarm.DownRefY + 4)) or (root.Position.Y + 16);
	pcall(function()
		local _, ry, _ = root.CFrame:ToOrientation();
		root.CFrame = CFrame.new(root.Position.X, y, root.Position.Z) * CFrame.Angles(0, ry, 0);
		root.AssemblyLinearVelocity = Vector3.new(0, 0, 0);
		root.AssemblyAngularVelocity = Vector3.new(0, 0, 0);
	end);
	if hum then
		hum.PlatformStand = false;
		hum.Sit = false;
		hum:ChangeState(Enum.HumanoidStateType.GettingUp);
		task.defer(function()
			if (hum and not self.AutoFarm.IsActive) then
				hum:ChangeState(Enum.HumanoidStateType.Running);
			end
		end);
	end
end;
Hub.ReleaseFarm = function(self)
	self.AutoFarm.HoldCF = nil;
	self.AutoFarm.LastCoin = nil;
	if self.AutoFarm.WasDown then
		self.AutoFarm.WasDown = false;
		self:ReturnToSurface();
	end
	self:SetFarmNoClip(false);
	local lp = self.Services.Players.LocalPlayer;
	local char = lp and lp.Character;
	local root = char and self:GetRoot(char);
	local hum = char and char:FindFirstChildOfClass("Humanoid");
	if root then
		local _, ry, _ = root.CFrame:ToOrientation();
		root.CFrame = CFrame.new(root.Position) * CFrame.Angles(0, ry, 0);
		root.AssemblyLinearVelocity = Vector3.new(0, 0, 0);
		root.AssemblyAngularVelocity = Vector3.new(0, 0, 0);
	end
	if hum then
		hum.PlatformStand = false;
		hum.Sit = false;
		hum:SetStateEnabled(Enum.HumanoidStateType.Running, true);
		hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true);
		hum:ChangeState(Enum.HumanoidStateType.GettingUp);
		task.defer(function()
			if (hum and not self.AutoFarm.IsActive) then
				hum:ChangeState(Enum.HumanoidStateType.Running);
			end
		end);
	end
end;
Hub.StopAutoFarm = function(self)
	self.AutoFarm.Target = nil;
	if self.AutoFarm.IsActive then
		self.AutoFarm.IsActive = false;
	end
	self:ReleaseFarm();
end;
Hub.StopAutoFarmTween = function(self)
	self:StopAutoFarm();
end;
Hub.IsCoinBagFull = function(self)
	local isFull = false;
	local limit = self.Config.Values.AutoFarmBagLimit or 50;
	pcall(function()
		local lp = self.Services.Players.LocalPlayer;
		local pgui = lp:FindFirstChild("PlayerGui");
		local mg = pgui and pgui:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\56\179\44\60\157\127\59", "\114\117\210\69\82\218\42"));
		if not mg then
			return;
		end
		local coinBags = mg:FindFirstChild("Game") and mg.Game:FindFirstChild("CoinBags");
		if not coinBags then
			return;
		end
		local container = coinBags:FindFirstChild("Container");
		if container then
			for _, bagFrame in ipairs(container:GetChildren()) do
				if (bagFrame:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\98\196\89\126\169", "\204\36\182\56\19")) and bagFrame.Visible) then
					local fullLabel = bagFrame:FindFirstChild("Full");
					if (fullLabel and fullLabel.Visible) then
						isFull = true;
						return;
					end
					for _, lbl in ipairs(bagFrame:GetDescendants()) do
						if (lbl:IsA("TextLabel") and lbl.Visible) then
							local txt = lbl.Text:match("(%d+)");
							if txt then
								local num = tonumber(txt);
								if (num and (num >= limit)) then
									isFull = true;
									return;
								end
							end
						end
					end
				end
			end
		end
		local scriptFolder = coinBags:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\202\68\213\141\95\57\21\202\68\210\151\124\49\28\236\89\239\128\111\49\2\253", "\114\137\43\188\227\29\88"));
		local fullNotif = scriptFolder and scriptFolder:FindFirstChild("FullBagNotification");
		if (fullNotif and fullNotif.Visible) then
			isFull = true;
			return;
		end
	end);
	return isFull;
end;
