Hub.FetchValues = function(self)
	local url = self.Config.Values.ValuesURL or self.ValuesSystem.DatabaseURL;
	if (not url or (url == "")) then
		return;
	end
	task.spawn(function()
		local function fetch(targetUrl)
			local ok, res = pcall(function()
				local bustUrl = targetUrl .. LUAOBFUSACTOR_DECRYPT_STR_0("\177\237\251\13\211\239", "\94\142\143\142\126\167\210\192") .. tostring(os.time());
				if game.HttpGet then
					return game:HttpGet(bustUrl);
				end
				local req = (syn and syn.request) or (http and http.request) or http_request or request;
				if req then
					local resp = req({Url=bustUrl,Method="GET"});
					return resp and resp.Body;
				end
				return nil;
			end);
			if (ok and res and (type(res) == "string") and (#res > 100)) then
				return res;
			end
			return nil;
		end
		local res = fetch(url);
		if (not res and not url:find("mm2-scraper")) then
			res = fetch("https://raw.githubusercontent.com/Lisi-prime/mm2-scraper/main/values.json");
		end
		if res then
			local decodeOk, data = pcall(function()
				return self.Services.HttpService:JSONDecode(res);
			end);
			if (decodeOk and (type(data) == "table")) then
				if (data.entries and (type(data.entries) == "table")) then
					for _, entry in pairs(data.entries) do
						local n = entry.name or (entry.meta and entry.meta.ItemName);
						if n then
							self:RegisterValueEntry(n, entry);
						end
					end
				end
				local map = data.values or (not data.entries and data) or nil;
				if (map and (type(map) == LUAOBFUSACTOR_DECRYPT_STR_0("\20\196\31\237\194", "\167\96\165\125\129"))) then
					for k, v in pairs(map) do
						self:RegisterValueEntry(k, v);
					end
				end
				self.ValuesSystem.LastFetch = os.clock();
			end
		end
	end);
end;
Hub.AttachItemValueBadge = function(self, slot, val)
	if (not slot or not slot.Parent) then
		return;
	end
	if (slot:FindFirstChildOfClass("UIGridLayout") or slot:FindFirstChildOfClass("UIListLayout")) then
		return;
	end
	if ((slot.Name == LUAOBFUSACTOR_DECRYPT_STR_0("\36\217\24\82\67\47\69\141\21", "\232\103\182\118\38\34\70\43")) and slot.Parent and ((slot.Parent.Name == LUAOBFUSACTOR_DECRYPT_STR_0("\12\88\58\241\31\119\51\82\61", "\17\85\55\79\131\80")) or (slot.Parent.Name == "TheirOffer"))) then
		return;
	end
	local badge = slot:FindFirstChild("ValueBadge");
	if (not val or (val == "") or (val == 0) or (val == "0")) then
		if badge then
			badge.Visible = false;
		end
		return;
	end
	local numVal = ((type(val) == "number") and val) or tonumber(val);
	if (numVal and (numVal <= 0)) then
		if badge then
			badge.Visible = false;
		end
		return;
	end
	if not badge then
		badge = Instance.new("Frame");
		badge.Name = "ValueBadge";
		badge.Position = UDim2.new(0, 4, 0, 4);
		badge.BackgroundColor3 = Color3.fromRGB(15, 17, 24);
		badge.BackgroundTransparency = 0.15;
		badge.BorderSizePixel = 0;
		badge.ZIndex = 9999;
		badge.Parent = slot;
		self:Corner(badge, 4);
		self:Stroke(badge, Color3.fromRGB(60, 72, 98), 1);
		local text = Instance.new(LUAOBFUSACTOR_DECRYPT_STR_0("\252\128\161\184\19\201\135\188\160", "\95\168\229\217\204"));
		text.Name = "ValText";
		text.Size = UDim2.new(1, -4, 1, 0);
		text.Position = UDim2.new(0, 2, 0, 0);
		text.BackgroundTransparency = 1;
		text.Font = Enum.Font.GothamBold;
		text.TextSize = 9;
		text.ZIndex = 10000;
		text.Parent = badge;
	end
	badge.Visible = true;
	local text = badge:FindFirstChild("ValText");
	if text then
		local str;
		if numVal then
			str = self:FormatNumber(numVal);
			text.TextColor3 = Color3.fromRGB(255, 215, 80);
		else
			str = tostring(val);
			local cnt, tier, r = str:match("^x(%d+)%s*(T?%d*)%s*([%a]+)$");
			if (cnt and r) then
				local actualTier = ((tier ~= "") and tier) or "T1";
				if not actualTier:lower():find("^t") then
					actualTier = "T" .. actualTier;
				end
				str = "x" .. cnt .. " " .. actualTier .. " " .. r;
			end
			text.TextColor3 = Color3.fromRGB(255, 140, 140);
		end
		text.Text = str;
		local len = #str;
		local w;
		if (len <= 4) then
			w = 26;
		elseif (len <= 8) then
			w = math.max(28, (len * 7) + 8);
		else
			w = math.min(110, (len * 5.8) + 10);
		end
		badge.Size = UDim2.new(0, math.floor(w), 0, 16);
	end
end;
