Hub.DecodeSkinEnum = function(self, raw)
	local group, item = string.match(raw, "^Enum%.([%w_]+)%.([%w_]+)$");
	if not group then
		return nil;
	end
	local ok, val = pcall(function()
		return Enum[group][item];
	end);
	return (ok and val) or nil;
end;
Hub.DecodeSkinProperty = function(self, current, raw)
	local k = type(raw);
	if ((k == LUAOBFUSACTOR_DECRYPT_STR_0("\201\152\176\119\6\46", "\92\167\237\221\21\99")) or (k == LUAOBFUSACTOR_DECRYPT_STR_0("\253\47\34\42\250\33\35", "\70\159\64\77"))) then
		return raw;
	end
	local want = typeof(current);
	if (k == LUAOBFUSACTOR_DECRYPT_STR_0("\196\91\64\246\20\208", "\122\183\47\50\159")) then
		if (want == LUAOBFUSACTOR_DECRYPT_STR_0("\231\63\178\66\169\214\52\170", "\224\162\81\199\47")) then
			return self:DecodeSkinEnum(raw);
		end
		return raw;
	end
	if (k ~= "table") then
		return nil;
	end
	if (want == LUAOBFUSACTOR_DECRYPT_STR_0("\222\64\48\41\140\250\22", "\227\136\37\83\93")) then
		return Vector3.new(raw[1], raw[2], raw[3]);
	elseif (want == "Vector2") then
		return Vector2.new(raw[1], raw[2]);
	elseif (want == "Color3") then
		return Color3.new(raw[1], raw[2], raw[3]);
	elseif (want == LUAOBFUSACTOR_DECRYPT_STR_0("\119\184\5\118\92\191\58\117\87\170\13", "\20\57\205\104")) then
		return NumberRange.new(raw[1], raw[2]);
	elseif (want == "CFrame") then
		return CFrame.new(table.unpack(raw));
	elseif (want == "NumberSequence") then
		local keys = {};
		for i = 1, #raw do
			local pt = raw[i];
			keys[i] = NumberSequenceKeypoint.new(pt.t, pt.v, pt.e or 0);
		end
		if (#keys < 2) then
			return NumberSequence.new((keys[1] and keys[1].Value) or 0);
		end
		return NumberSequence.new(keys);
	elseif (want == "ColorSequence") then
		local keys = {};
		for i = 1, #raw do
			local pt = raw[i];
			local rgb = pt.c;
			keys[i] = ColorSequenceKeypoint.new(pt.t, Color3.new(rgb[1], rgb[2], rgb[3]));
		end
		if (#keys < 2) then
			return ColorSequence.new((keys[1] and keys[1].Value) or Color3.new(1, 1, 1));
		end
		return ColorSequence.new(keys);
	end
	return nil;
end;
Hub.ApplySkinProps = function(self, inst, props)
	if (type(props) ~= "table") then
		return inst;
	end
	for key, raw in pairs(props) do
		if not skinPropNope[key] then
			local ok, curr = pcall(function()
				return inst[key];
			end);
			if ok then
				local val = self:DecodeSkinProperty(curr, raw);
				if (val ~= nil) then
					pcall(function()
						inst[key] = val;
					end);
				end
			end
		end
	end
	return inst;
end;
Hub.RegisterSkinGarbage = function(self, owner, inst)
	if (not owner or not inst) then
		return inst;
	end
	local list = self.SkinSystem.Musor[owner];
	if not list then
		list = {};
		self.SkinSystem.Musor[owner] = list;
	end
	list[#list + 1] = inst;
	return inst;
end;
Hub.ClearSkinGarbage = function(self, owner)
	local list = self.SkinSystem.Musor[owner];
	if not list then
		return;
	end
	for i = #list, 1, -1 do
		local inst = list[i];
		if inst then
			pcall(function()
				inst:Destroy();
			end);
		end
		list[i] = nil;
	end
end;
Hub.BackupSkinProp = function(self, inst, data)
	if not inst then
		return;
	end
	if not self.SkinSystem.Saved[inst] then
		self.SkinSystem.Saved[inst] = data;
	end
end;
Hub.CreateSkinPart = function(self, rec)
	local root = rec.display and rec.display.root;
	local props = root and root.props;
	if not props then
		return nil;
	end
	if props.MeshId then
		local numId = tonumber(string.match(tostring(props.MeshId), "(%d+)"));
		if numId then
			local base = self.SkinSystem.Meshes[numId];
			if not base then
				local ok, mesh;
				if (Content and Content.fromAssetId and self.Services.AssetService and self.Services.AssetService.CreateMeshPartAsync) then
					ok, mesh = pcall(self.Services.AssetService.CreateMeshPartAsync, self.Services.AssetService, Content.fromAssetId(numId));
				end
				if (not ok or not mesh) then
					local part = Instance.new(LUAOBFUSACTOR_DECRYPT_STR_0("\24\170\10\173", "\83\72\203\120\217\122\58"));
					local sm = Instance.new(LUAOBFUSACTOR_DECRYPT_STR_0("\143\249\190\160\166\188\179\145\236\168\171", "\223\220\137\219\195\207\221"));
					sm.MeshType = Enum.MeshType.FileMesh;
					sm.MeshId = tostring(props.MeshId);
					if props.TextureID then
						sm.TextureId = tostring(props.TextureID);
					end
					sm.Parent = part;
					mesh = part;
				end
				mesh.Parent = nil;
				self.SkinSystem.Meshes[numId] = mesh;
				base = mesh;
			end
			local part = base:Clone();
			self:ApplySkinProps(part, props);
			if (type(props.Size) == "table") then
				part.Size = Vector3.new(props.Size[1], props.Size[2], props.Size[3]);
			end
			part.Anchored = false;
			part.Massless = true;
			part.CanCollide = false;
			part.CanQuery = false;
			part.CanTouch = false;
			part.Locked = true;
			return part;
		end
	end
	local specialNode = nil;
	if (type(rec.display and rec.display.nodes) == "table") then
		for _, n in ipairs(rec.display.nodes) do
			if ((n.class == "SpecialMesh") and not n.parent and n.props and n.props.MeshId) then
				specialNode = n;
				break;
			end
		end
	end
	if specialNode then
		local part = Instance.new(LUAOBFUSACTOR_DECRYPT_STR_0("\35\73\77\246", "\76\115\40\63\130"));
		self:ApplySkinProps(part, props);
		if (type(props.Size) == "table") then
			part.Size = Vector3.new(props.Size[1], props.Size[2], props.Size[3]);
		end
		part.Anchored = false;
		part.Massless = true;
		part.CanCollide = false;
		part.CanQuery = false;
		part.CanTouch = false;
		part.Locked = true;
		local mesh = Instance.new(LUAOBFUSACTOR_DECRYPT_STR_0("\180\10\40\174\191\208\139\55\40\190\190", "\177\231\122\77\205\214"));
		mesh.Name = specialNode.name or "Mesh";
		mesh.MeshType = Enum.MeshType.FileMesh;
		self:ApplySkinProps(mesh, specialNode.props);
		pcall(function()
			mesh.MeshId = specialNode.props.MeshId;
		end);
		mesh.Parent = part;
		return part;
	end
	return nil;
end;
Hub.ApplySkinFX = function(self, rec, owner, body, handle)
	local paths = {};
	local sounds = {};
	local nodes = rec.display and rec.display.nodes;
	if (type(nodes) ~= "table") then
		return sounds;
	end
	for _, node in ipairs(nodes) do
		local class = node.class;
		if skinFxClasses[class] then
			local parent = node.parent and paths[node.parent];
			if not parent then
				parent = (skinOnHandleClasses[class] and handle) or body;
			end
			local inst = Instance.new(class);
			inst.Name = node.name or class;
			self:ApplySkinProps(inst, node.props);
			inst.Parent = parent;
			if node.tags then
				for _, t in ipairs(node.tags) do
					pcall(self.Services.CollectionService.AddTag, self.Services.CollectionService, inst, t);
				end
			end
			if node.attrs then
				for k, v in pairs(node.attrs) do
					pcall(function()
						inst:SetAttribute(k, v);
					end);
				end
			end
			if node.path then
				paths[node.path] = inst;
			end
			if (class == "Sound") then
				sounds[node.name] = inst;
			end
			self:RegisterSkinGarbage(owner, inst);
		end
	end
	return sounds;
end;
Hub.FindToolBySlot = function(self, slot)
	local lp = self.Services.Players.LocalPlayer;
	local char = lp and lp.Character;
	local tool = char and char:FindFirstChild(slot);
	if (tool and tool:IsA("Tool")) then
		return tool;
	end
	local bp = lp and lp:FindFirstChildOfClass("Backpack");
	tool = bp and bp:FindFirstChild(slot);
	if (tool and tool:IsA("Tool")) then
		return tool;
	end
	return nil;
end;
Hub.FindDisplayPedestal = function(self, slot)
	local lp = self.Services.Players.LocalPlayer;
	local char = lp and lp.Character;
	local ref = char and char:FindFirstChild("DisplayRef" .. slot);
	local part = ref and ref.Value;
	if (part and part.Parent) then
		return part;
	end
	return nil;
end;
Hub.ApplySkinToTool = function(self, rec)
	local slot = rec.kind or (rec.meta and rec.meta.ItemType) or "Knife";
	local tool = self:FindToolBySlot(slot);
	if not tool then
		return false;
	end
	local handle = tool:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\108\18\79\68\165\89", "\60\36\115\33\32\201")) or tool:FindFirstChildWhichIsA("BasePart");
	if not handle then
		return false;
	end
	self:BackupSkinProp(tool, {grip=tool.Grip});
	self:BackupSkinProp(handle, {size=handle.Size,[LUAOBFUSACTOR_DECRYPT_STR_0("\163\100\86\72\95", "\193\215\22\55\38\44\62\93")]=handle.Transparency,mod=handle.LocalTransparencyModifier});
	self:ClearSkinGarbage(tool);
	local body = self:CreateSkinPart(rec);
	if not body then
		return false;
	end
	body.Name = "CustomSkinMesh";
	body.Parent = tool;
	body.CFrame = handle.CFrame;
	self:RegisterSkinGarbage(tool, body);
	local weld = Instance.new("WeldConstraint");
	weld.Part0 = handle;
	weld.Part1 = body;
	weld.Parent = body;
	self:RegisterSkinGarbage(tool, weld);
	if (rec.display and rec.display.root and rec.display.root.props and rec.display.root.props.Size) then
		local sz = rec.display.root.props.Size;
		handle.Size = Vector3.new(sz[1], sz[2], sz[3]);
	end
	handle.LocalTransparencyModifier = 1;
	pcall(function()
		handle.Transparency = 1;
	end);
	local toolRoot = rec.tool and rec.tool.root;
	local grip = toolRoot and toolRoot.props and toolRoot.props.Grip;
	if (grip and (#grip >= 12)) then
		pcall(function()
			tool.Grip = CFrame.new(table.unpack(grip));
		end);
	end
	local sounds = self:ApplySkinFX(rec, tool, body, handle);
	if next(sounds) then
		for _, inst in ipairs(tool:GetDescendants()) do
			if (inst:IsA("Sound") and not sounds[inst.Name]) then
				self:BackupSkinProp(inst, {[LUAOBFUSACTOR_DECRYPT_STR_0("\57\29\2\218\216\254", "\155\79\114\110\175\181")]=inst.Volume});
				pcall(function()
					inst.Volume = 0;
				end);
			end
		end
	end
	return true;
end;
Hub.ApplySkinToDisplay = function(self, rec)
	if not self.SkinSystem.LobbyPedestal then
		return false;
