			end);
		end
		local c1 = char.ChildAdded:Connect(triggerMorphUpdate);
		local c2 = char.ChildRemoved:Connect(triggerMorphUpdate);
		local c3 = char.DescendantAdded:Connect(function(d)
			if (d:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\80\137\19\27\139\59\215\194", "\182\18\232\96\126\219\90\165")) or d:IsA("CharacterMesh") or d:IsA("Shirt") or d:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\13\95\41\188\46", "\200\93\62\71")) or d:IsA("Accessory") or d:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\117\93\75\217\205\179\2\107\72\93\210", "\110\38\45\46\186\164\210"))) then
				triggerMorphUpdate();
			end
		end);
		local c4 = char.DescendantRemoving:Connect(function(d)
			if (d:IsA("BasePart") or d:IsA("CharacterMesh") or d:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\75\182\161\4\42", "\94\24\222\200\118")) or d:IsA("Pants") or d:IsA("Accessory") or d:IsA("SpecialMesh")) then
				triggerMorphUpdate();
			end
		end);
		table.insert(self.State.Connections, c1);
		table.insert(self.State.Connections, c2);
		table.insert(self.State.Connections, c3);
		table.insert(self.State.Connections, c4);
