			self:CloneLocalPlayerModel();
		end
	end);
end;
Hub.SetupAutoRejoin = function(self)
	local ts = self.Services.TeleportService;
	local gs = self.Services.GuiService;
	local lp = self.Services.Players.LocalPlayer;
	local rejoinScheduled = false;
	local function handleKick()
		if (rejoinScheduled or not self.Config.Toggles.AutoRejoin) then
			return;
		end
		rejoinScheduled = true;
		pcall(function()
			if (syn and syn.queue_on_teleport) then
				syn.queue_on_teleport("loadstring(game:HttpGet('https://raw.githubusercontent.com/Lisi-prime/Dynamic-Hub/main/source.lua'))()");
			elseif queue_on_teleport then
				queue_on_teleport("loadstring(game:HttpGet('https://raw.githubusercontent.com/Lisi-prime/Dynamic-Hub/main/source.lua'))()");
			end
		end);
		pcall(function()
			local screen = self.State.Gui or (gethui and gethui()) or self.Services.CoreGui;
			local notif = Instance.new("Frame");
			notif.Size = UDim2.new(0, 360, 0, 70);
			notif.Position = UDim2.new(0.5, -180, 0.15, 0);
			notif.BackgroundColor3 = Color3.fromRGB(24, 24, 32);
			notif.BorderSizePixel = 0;
			notif.ZIndex = 99999;
			notif.Parent = screen;
			self:Corner(notif, 10);
			self:Stroke(notif, Color3.fromRGB(240, 80, 90), 2);
			local lbl = Instance.new("TextLabel");
			lbl.Size = UDim2.new(1, -20, 1, 0);
			lbl.Position = UDim2.new(0, 10, 0, 0);
			lbl.BackgroundTransparency = 1;
			lbl.Font = Enum.Font.GothamBold;
			lbl.Text = "Disconnected / Kicked! Rejoining in 3 seconds...";
			lbl.TextColor3 = Color3.fromRGB(255, 255, 255);
			lbl.TextSize = 13;
			lbl.ZIndex = 100000;
			lbl.Parent = notif;
		end);
		task.spawn(function()
			while true do
				pcall(function()
					ts:Teleport(game.PlaceId, lp);
				end);
				task.wait(2.5);
				pcall(function()
					ts:TeleportToPlaceInstance(game.PlaceId, game.JobId, lp);
				end);
				task.wait(2.5);
			end
		end);
	end
	pcall(function()
		gs.ErrorMessageChanged:Connect(function(msg)
			if (msg and (#msg > 0)) then
				handleKick();
			end
