Hub.SwitchTab = function(self, tabName)
	self.Config.ActiveTab = tabName;
	if self.State.SubHeaderIcon then
		self.State.SubHeaderIcon.Image = Icons[tabName] or Icons.Combat;
	end
	if self.State.SubHeaderTitle then
		self.State.SubHeaderTitle.Text = tabName;
	end
	if self.State.SearchBox then
		self.State.SearchBox.Text = "";
	end
	local activeBtnData = self.State.TabButtons[tabName];
	if (activeBtnData and self.State.TabIndicator and self.State.NavCapsule) then
		local btn = activeBtnData.Button;
		local order = activeBtnData.LayoutOrder or 1;
		local targetX = 4 + ((order - 1) * 80);
		local targetY = 3;
		if ((btn.AbsolutePosition.X > 0) and (self.State.NavCapsule.AbsolutePosition.X > 0)) then
			local relX = btn.AbsolutePosition.X - self.State.NavCapsule.AbsolutePosition.X;
			local relY = btn.AbsolutePosition.Y - self.State.NavCapsule.AbsolutePosition.Y;
			if ((relX >= 0) and (relY >= 0)) then
				targetX = relX;
				targetY = relY;
			end
		end
		self:Tween(self.State.TabIndicator, {[LUAOBFUSACTOR_DECRYPT_STR_0("\179\119\189\208\42\67\32\138", "\228\227\24\206\185\94\42\79")]=UDim2.new(0, targetX, 0, targetY),[LUAOBFUSACTOR_DECRYPT_STR_0("\253\43\45\173", "\80\174\66\87\200\212\123")]=UDim2.new(0, ((btn.AbsoluteSize.X > 0) and btn.AbsoluteSize.X) or 76, 0, ((btn.AbsoluteSize.Y > 0) and btn.AbsoluteSize.Y) or 24)}, 0.28, Enum.EasingStyle.Quart, Enum.EasingDirection.Out);
	end
	for name, data in pairs(self.State.TabButtons) do
		local page = self.State.Tabs[name];
		if (name == tabName) then
			page.Visible = true;
			task.defer(function()
				local wrapper = page:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\239\108\63\196\212\28\199\78\44\201\231\3\206\107", "\115\171\25\94\168\151"));
				if wrapper then
					local leftCol = wrapper:FindFirstChild("LeftCol");
					local rightCol = wrapper:FindFirstChild("RightCol");
					local leftLayout = leftCol and leftCol:FindFirstChildOfClass("UIListLayout");
					local rightLayout = rightCol and rightCol:FindFirstChildOfClass("UIListLayout");
					local lh = (leftLayout and leftLayout.AbsoluteContentSize.Y) or (leftCol and leftCol.AbsoluteSize.Y) or 0;
					local rh = (rightLayout and rightLayout.AbsoluteContentSize.Y) or (rightCol and rightCol.AbsoluteSize.Y) or 0;
					local maxH = math.max(lh, rh);
					if (maxH > 40) then
						wrapper.Size = UDim2.new(1, 0, 0, maxH + 20);
						page.CanvasSize = UDim2.new(0, 0, 0, maxH + 50);
					end
				end
			end);
			task.delay(0.08, function()
				local wrapper = page:FindFirstChild("DualColWrapper");
				if wrapper then
					local leftCol = wrapper:FindFirstChild("LeftCol");
					local rightCol = wrapper:FindFirstChild("RightCol");
					local leftLayout = leftCol and leftCol:FindFirstChildOfClass("UIListLayout");
					local rightLayout = rightCol and rightCol:FindFirstChildOfClass("UIListLayout");
					local lh = (leftLayout and leftLayout.AbsoluteContentSize.Y) or (leftCol and leftCol.AbsoluteSize.Y) or 0;
					local rh = (rightLayout and rightLayout.AbsoluteContentSize.Y) or (rightCol and rightCol.AbsoluteSize.Y) or 0;
					local maxH = math.max(lh, rh);
					if (maxH > 40) then
						wrapper.Size = UDim2.new(1, 0, 0, maxH + 20);
						page.CanvasSize = UDim2.new(0, 0, 0, maxH + 50);
					end
				end
			end);
			data.Title.Font = Enum.Font.GothamBold;
			data.Button.BackgroundTransparency = 1;
			self:Tween(data.Title, {TextColor3=Color3.fromRGB(18, 18, 22)}, 0.2);
			if data.Icon then
				self:Tween(data.Icon, {ImageColor3=Color3.fromRGB(18, 18, 22)}, 0.2);
			end
		else
			page.Visible = false;
			data.Title.Font = Enum.Font.GothamMedium;
			data.Button.BackgroundTransparency = 1;
